Ltac name_as_by_tac X e tac :=
  set (X := e) in *;
  let RX := fresh "R" X in
  assert (RX : 0 <= X < 18446744073709551616) by (subst X; tac).
Tactic Notation "name_as_by" ident(X) constr(e) tactic3(tac) := name_as_by_tac X e tac.

