(* [comment removed for export] *)
Ltac reg_rewrite n lem :=
  let w := getreg n in
  lazymatch w with
  | Z_to_bv 64 ?e =>
      let e' := fresh "e" in let E := fresh "E" in
      remember e as e' eqn:E in |- *;
      rewrite lem in E; subst e'
  end.

